#include <vector>
#include <algorithm>

class Solution {
public:
    /**
     * 方法一：快慢指標 + 賦值
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    void moveZeroes(std::vector<int>& nums) {
        int slow = 0;

        // 將所有非零元素移到前面
        for (int fast = 0; fast < nums.size(); fast++) {
            if (nums[fast] != 0) {
                nums[slow] = nums[fast];
                slow++;
            }
        }

        // 將 slow 到末尾的位置填充 0
        for (int i = slow; i < nums.size(); i++) {
            nums[i] = 0;
        }
    }

    /**
     * 方法二：快慢指標 + 交換（推薦）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    void moveZeroes_swap(std::vector<int>& nums) {
        int slow = 0;

        for (int fast = 0; fast < nums.size(); fast++) {
            if (nums[fast] != 0) {
                std::swap(nums[slow], nums[fast]);
                slow++;
            }
        }
    }
};

