class Solution {
    /**
     * 方法一：快慢指標 + 賦值
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    public void moveZeroes(int[] nums) {
        int slow = 0;

        // 將所有非零元素移到前面
        for (int fast = 0; fast < nums.length; fast++) {
            if (nums[fast] != 0) {
                nums[slow] = nums[fast];
                slow++;
            }
        }

        // 將 slow 到末尾的位置填充 0
        for (int i = slow; i < nums.length; i++) {
            nums[i] = 0;
        }
    }

    /**
     * 方法二：快慢指標 + 交換（推薦）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    public void moveZeroes_swap(int[] nums) {
        int slow = 0;

        for (int fast = 0; fast < nums.length; fast++) {
            if (nums[fast] != 0) {
                // 交換
                int temp = nums[slow];
                nums[slow] = nums[fast];
                nums[fast] = temp;
                slow++;
            }
        }
    }
}

