// 雙指標：slow 指向下一個非零元素該放的位置
// 時間複雜度: O(n)，空間複雜度: O(1)
void moveZeroes(int* nums, int numsSize) {
    int slow = 0;
    for (int fast = 0; fast < numsSize; fast++) {
        if (nums[fast] != 0) nums[slow++] = nums[fast];
    }
    while (slow < numsSize) nums[slow++] = 0;    // 剩下的位置補 0
}
